SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_918
WHERE kt.id = non_leaf_918.t_kind_id AND it2.id = pi.info_type_id AND ci.role_id = rt.id AND (it1.id IN ('16')) AND (pi.info ILIKE '%193%') AND (mi1.info ILIKE '%co%') AND ci.movie_id = non_leaf_918.mi1_movie_id AND (it2.id IN ('23')) AND (kt.kind IN ('episode','tv mini series','tv movie')) AND (rt.role IN ('actress','cinematographer','composer','costume designer','director','editor','producer','production designer','writer')) AND ci.movie_id = non_leaf_918.t_id AND ci.person_id = n.id AND n.id = pi.person_id AND it1.id = non_leaf_918.mi1_info_type_id;